using System.Text.Json;
using Microsoft.Data.Sqlite;
namespace BeastCloud;

public sealed partial class Cloud
{
    static void MapAdministration(WebApplication app)
    {
        app.MapGet("/api/settings", (Cloud x) => new { displayName = x.db.Setting("displayName", "Owner"), appearance = x.db.Setting("appearance", "dark"), timezone = x.db.Setting("timezone", "UTC"), language = x.db.Setting("language", "en"), dateFormat = x.db.Setting("dateFormat", "yyyy-MM-dd"), backupDestination = x.db.Setting("backupDestination", Path.Combine(x.disk.Root, "backups")), backupHours = x.db.Setting("backupHours", "0"), retentionDays = x.db.Setting("retentionDays", "0"), backupKeep = x.db.Setting("backupKeep", "14"), thumbnailLimit = x.db.Setting("thumbnailLimit", "536870912"), uploadLimit = x.db.Setting("uploadLimit", (100L * 1024 * 1024 * 1024).ToString()), storage = x.disk.Files, root = x.disk.Root, network = "Managed by the local installer. Default: loopback HTTPS only." });
        app.MapPut("/api/settings", async (HttpContext c, Cloud x, JsonElement j) => { await Locked(x.disk, () => { foreach (var prop in j.EnumerateObject()) { if (prop.Name is "displayName" or "appearance" or "timezone" or "language" or "dateFormat" or "backupDestination" or "backupHours" or "retentionDays" or "uploadLimit" or "backupKeep" or "thumbnailLimit") { var val = prop.Value.GetString() ?? ""; if (prop.Name == "backupDestination") Backup.ValidateDestination(x.disk, val); if (prop.Name is "backupHours" or "retentionDays" or "uploadLimit" or "backupKeep" or "thumbnailLimit") { if (!long.TryParse(val, out var n) || n < 0) throw new ArgumentException("Invalid numeric setting"); } if (prop.Name == "timezone") _ = TimeZoneInfo.FindSystemTimeZoneById(val); x.db.Set(prop.Name, val); } } x.db.Audit(Actor(c), "settings.updated"); return Task.CompletedTask; }); return Results.Ok(); });
        app.MapGet("/api/activity", (Database d, int? page) => d.Rows("SELECT * FROM audit ORDER BY id DESC LIMIT 200 OFFSET $o", ("$o", Math.Max(0, page ?? 0) * 200)));
        app.MapGet("/api/jobs", (Database d) => d.Rows("SELECT * FROM jobs ORDER BY created DESC LIMIT 100"));
        app.MapPost("/api/jobs/{id}/retry", (Database d, string id) => { d.Execute("UPDATE jobs SET state='pending',attempts=0,error=NULL WHERE id=$id AND state='failed'", ("$id", id)); return Results.Ok(); });
        app.MapPost("/api/search/rebuild", (Database d) => { d.Job("rebuild", ""); return Results.Accepted(); });
        app.MapPost("/api/backups", (HttpContext c, Database d) => { d.Job("backup", ""); d.Audit(Actor(c), "backup.requested"); return Results.Accepted(); });
        app.MapGet("/api/backups", (Cloud x) => { var dir = x.db.Setting("backupDestination", Path.Combine(x.disk.Root, "backups")); return new { destination = dir, available = Directory.Exists(dir), jobs = x.db.Rows("SELECT * FROM jobs WHERE type='backup' ORDER BY created DESC LIMIT 100") }; });
        app.MapPost("/api/export", (HttpContext c, Database d, JsonElement j) => { var destination = S(j, "destination") ?? ""; if (!Path.IsPathFullyQualified(destination)) throw new ArgumentException("An absolute destination is required"); d.Job("export", destination); d.Audit(Actor(c), "export.requested"); return Results.Accepted(); });
    }
}
public static class Backup
{
    public static void ValidateDestination(Storage s, string destination) { if (!Path.IsPathFullyQualified(destination)) throw new ArgumentException("Choose an absolute backup path"); var p = Path.TrimEndingDirectorySeparator(Path.GetFullPath(destination)); var sources = new[] { s.Files, s.Data, Path.Combine(s.Root, "config"), Path.Combine(s.Root, "app") }; foreach (var source in sources) { var a = Path.TrimEndingDirectorySeparator(Path.GetFullPath(source)); if (p.Equals(a, StringComparison.OrdinalIgnoreCase) || p.StartsWith(a + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) || a.StartsWith(p + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) throw new ArgumentException("Backup must be separate from application data and configuration"); } Storage.CheckPath(destination); if (!Directory.Exists(destination)) throw new IOException("Backup destination is unavailable. Create it explicitly first."); }
    public static async Task<string> Create(Database db, Storage s)
    {
        var dest = db.Setting("backupDestination", Path.Combine(s.Root, "backups")); ValidateDestination(s, dest); s.Available(); var target = Path.Combine(dest, DateTime.UtcNow.ToString("yyyyMMdd-HHmmss") + "-" + Cloud.Id()[..8]); var pending = target + ".partial"; Directory.CreateDirectory(pending); try
        {
            Directory.CreateDirectory(Path.Combine(pending, "data", "db")); using (var source = db.Open()) using (var copy = new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(pending,"data","db","beast.db"),Pooling=false}.ToString())) { copy.Open(); source.BackupDatabase(copy); }
            Directory.CreateDirectory(Path.Combine(pending, "data", "files")); var blobs = db.Rows("SELECT blob FROM items WHERE blob IS NOT NULL UNION SELECT blob FROM versions"); foreach (var blob in blobs) { var id = (string)blob["blob"]!; File.Copy(s.Blob(id), Path.Combine(pending, "data", "files", id)); }
            foreach (var f in Directory.GetFiles(Path.Combine(s.Root, "config"))) { if (Path.GetFileName(f) is "storage.json" or "instance.lock" or "setup.key" or "installation.json") continue; if((File.GetAttributes(f)&FileAttributes.ReparsePoint)!=0)throw new IOException("Unsafe configuration link");File.Copy(f, Path.Combine(pending, Path.GetFileName(f))); }
            var manifest = new Dictionary<string, string>(); foreach (var f in Directory.GetFiles(pending, "*", SearchOption.AllDirectories)) manifest[Path.GetRelativePath(pending, f).Replace('\\', '/')] = await Storage.Checksum(f); await File.WriteAllTextAsync(Path.Combine(pending, "manifest.json"), JsonSerializer.Serialize(new { format = 1, version = "0.1.0", created = Database.Now, files = manifest })); Directory.Move(pending, target); db.Audit("worker", "backup.completed", Path.GetFileName(target)); return target;
        }
        catch { if (Directory.Exists(pending)) Directory.Delete(pending, true); throw; }
    }
    public static async Task Verify(string source) { using var j = JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(source, "manifest.json"))); if (j.RootElement.GetProperty("format").GetInt32() != 1) throw new ArgumentException("Unsupported backup format"); foreach (var p in j.RootElement.GetProperty("files").EnumerateObject()) { var full = SafeChild(source, p.Name); if (!File.Exists(full) || await Storage.Checksum(full) != p.Value.GetString()) throw new IOException("Backup integrity check failed: " + p.Name); } using var db = new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=SafeChild(source,"data/db/beast.db"),Pooling=false}.ToString()); db.Open(); using var q = db.CreateCommand(); q.CommandText = "PRAGMA integrity_check"; if ((string?)q.ExecuteScalar() != "ok") throw new IOException("Backup database is corrupt"); }
    static string SafeChild(string root, string relative) { if (Path.IsPathRooted(relative) || relative.Split('/', '\\').Any(x => x is ".." or "." || x.Contains(':'))) throw new ArgumentException("Unsafe backup path"); var path = Path.GetFullPath(Path.Combine(root, relative)); if (!path.StartsWith(Path.GetFullPath(root) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) throw new ArgumentException("Unsafe backup path"); Storage.CheckPath(Path.GetDirectoryName(path)!); if (File.Exists(path) && (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0) throw new IOException("Unsafe backup link"); return path; }
    public static async Task Restore(string source, string target) { if (Directory.Exists(target) && Directory.EnumerateFileSystemEntries(target).Any()) throw new ArgumentException("Restore requires a new empty destination"); await Verify(source); Directory.CreateDirectory(target); using var j = JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(source, "manifest.json"))); foreach (var p in j.RootElement.GetProperty("files").EnumerateObject()) { var rel = p.Name; var dest = rel.StartsWith("data/") ? SafeChild(target, rel) : SafeChild(target, "config/" + rel); Directory.CreateDirectory(Path.GetDirectoryName(dest)!); File.Copy(SafeChild(source, rel), dest); } var s = new Storage(target, null); var d = new Database(Path.Combine(s.Data, "db", "beast.db")); d.Initialize(); d.Execute("DELETE FROM sessions"); d.Execute("UPDATE devices SET token=NULL,pair=NULL"); d.Execute("DELETE FROM uploads"); d.Execute("UPDATE jobs SET state='failed',error='Restore invalidated in-flight work' WHERE state IN ('pending','running')"); d.Set("backupDestination", Path.Combine(target, "backups")); var config = Path.Combine(target, "config", "server.json"); if (File.Exists(config)) { var node = System.Text.Json.Nodes.JsonNode.Parse(await File.ReadAllTextAsync(config))!; if (node["Kestrel"]?["Endpoints"] is System.Text.Json.Nodes.JsonObject endpoints) { endpoints.Remove("Lan"); foreach (var endpoint in endpoints) { if (endpoint.Value?["Certificate"] is { } certificate) certificate["Path"] = Path.Combine(Path.GetFullPath(target), "config", "https.pfx"); } } await File.WriteAllTextAsync(config, node.ToJsonString(new() { WriteIndented = true })); } Console.WriteLine("Restore verified. Sessions and device credentials revoked. Reissue TLS certificates for a different host."); }
    public static async Task Export(Database db, Storage s, string target) { if (Directory.Exists(target)) throw new ArgumentException("Export destination must not already exist"); ValidateDestination(s, Path.GetDirectoryName(target)!); Directory.CreateDirectory(target); var items = db.Rows("SELECT * FROM items WHERE deleted IS NULL"); var map = items.ToDictionary(i => (string)i["id"]!); string Relative(Dictionary<string, object?> i) { var parts = new List<string> { Storage.Name((string)i["name"]!) }; var p = i["parent"] as string; var seen = new HashSet<string>(); while (p != null && map.TryGetValue(p, out var parent) && seen.Add(p)) { parts.Add(Storage.Name((string)parent["name"]!)); p = parent["parent"] as string; } parts.Reverse(); return Path.Combine(parts.ToArray()); } foreach (var i in items.OrderBy(i => (string)i["kind"] == "folder" ? 0 : 1)) { var path = Path.Combine(target, Relative(i)); if ((string)i["kind"] == "folder") Directory.CreateDirectory(path); else { Directory.CreateDirectory(Path.GetDirectoryName(path)!); File.Copy(s.Blob((string)i["blob"]!), path); } } var records = Path.Combine(target, ".beastcloud-records");if(Directory.Exists(records)||File.Exists(records))records+="-"+Cloud.Id()[..8]; Directory.CreateDirectory(records); await File.WriteAllTextAsync(Path.Combine(records, "records.json"), JsonSerializer.Serialize(db.Rows("SELECT * FROM records"))); foreach (var n in db.Rows("SELECT * FROM records WHERE type='note'")) { var b = JsonDocument.Parse((string)n["body"]!).RootElement; await File.WriteAllTextAsync(Path.Combine(records, (string)n["id"]! + ".md"), Cloud.S(b, "text") ?? ""); } await File.WriteAllTextAsync(Path.Combine(records, "calendar.ics"), Calendar.Export(db.Rows("SELECT * FROM records WHERE type='event'"))); }
}
